#!/usr/bin/env python3
"""Generate lean/TwinPrimes/Tuples.lean from the tuples found by admissible.py."""
import json, os
T = {int(k): v for k, v in json.load(open("code/tuples.json")).items()}
for extra in ("code/tuples_mid.json", "code/tuples_big.json"):
    if os.path.exists(extra):
        T.update({int(k): v for k, v in json.load(open(extra)).items()})
L = ["import TwinPrimes.Basic", "",
     "/-!", "# Explicit narrow admissible tuples, checked by the kernel", "",
     "Generated by `code/gen_lean.py` from `code/tuples.json`.  Each `narrow k`",
     "is an admissible `k`-tuple in `[0, D]`; all four fields are closed by `decide`.",
     "Consequence: `DHL k → BoundedGaps D` for each listed pair `(k, D)`.", "-/", "",
     "namespace TwinPrimes", "", "set_option maxRecDepth 100000", ""]
for k in sorted(T):
    H = T[k]; D = H[-1]
    L += [f"def narrow{k} : NarrowTuple {k} {D} where",
          f"  H := {H}",
          "  len := by decide", "  sorted := by decide +kernel",
          "  bound := by decide +kernel", "  check := by decide +kernel", "",
          f"theorem boundedGaps_{D}_of_DHL_{k} (h : DHL {k}) : BoundedGaps {D} :=",
          f"  narrow{k}.boundedGaps h", ""]
L += ["/-- The endpoint: `DHL[2,2]` for the tuple `(0, 2)` is the twin prime conjecture. -/",
      "theorem twinPrimeConjecture_of_DHL_2 (h : DHL 2) : TwinPrimeConjecture :=",
      "  twin_iff.mpr (boundedGaps_2_of_DHL_2 h)", "", "end TwinPrimes", ""]
open("lean/TwinPrimes/Tuples.lean", "w").write("\n".join(L))
print("wrote", len(T), "tuples")
